import {normalizeLayout,presetLayout,clamp,escapeHTML} from './core.js';
import {isMobileScreen,mobilePanelVisible,mixerDecks} from './mobile.js';
export const PANEL_NAMES={waves:'波形ビュー',deck0:'DECK A',deck1:'DECK B',deck2:'DECK C',deck3:'DECK D',mixer:'ミキサー',library:'ライブラリ',sampler:'サンプラー'};
export class LayoutManager{
 constructor(root,getState,save,onChange){this.root=root;this.getState=getState;this.save=save;this.onChange=onChange;this.editing=false;this.undoStack=[];this.redoStack=[];this.drag=null;this.root.addEventListener('pointerdown',e=>this.down(e));window.addEventListener('pointermove',e=>this.move(e));window.addEventListener('pointerup',e=>this.up(e));window.addEventListener('pointercancel',e=>this.up(e));this.observer=new ResizeObserver(()=>this.apply());this.observer.observe(root);window.addEventListener('resize',()=>this.apply());}
 checkpoint(){this.undoStack.push(structuredClone(this.getState().layout));this.undoStack=this.undoStack.slice(-30);this.redoStack=[];}
 apply(){const s=this.getState(),mobile=isMobileScreen(),col=this.root.clientWidth/24;let bottom=0;for(const [id,p]of Object.entries(s.layout)){const el=this.root.querySelector(`[data-panel="${id}"]`);if(!el)continue;el.hidden=mobile?!mobilePanelVisible(id,s.mobile):!p.visible;if(el.hidden)continue;if(mobile){el.style.cssText=`--panel-order:${p.y*24+p.x};`;el.classList.remove('narrow');}else{el.style.left=`${p.x*col+4}px`;el.style.top=`${p.y*20+4}px`;el.style.width=`${p.w*col-8}px`;el.style.height=`${p.h*20-8}px`;el.classList.toggle('narrow',p.w*col<450);}bottom=Math.max(bottom,(p.y+p.h)*20);}
 document.body.dataset.ui=mobile?'mobile':'desktop';document.body.dataset.mobileView=s.mobile.view;document.body.dataset.mobileDeck=s.mobile.deck;this.root.querySelectorAll('[data-wave-lane]').forEach(el=>{el.hidden=mobile?Number(el.dataset.waveLane)!==s.mobile.deck:!s.layout['deck'+el.dataset.waveLane].visible;});const indices=mixerDecks(s,mobile);this.root.querySelectorAll('[data-channel]').forEach(el=>el.hidden=!indices.includes(Number(el.dataset.channel)));this.root.querySelector('.mixer-channels')?.style.setProperty('--channels',indices.length);this.root.classList.toggle('mobile-workspace',mobile);this.root.classList.toggle('layout-editing',this.editing&&!mobile);this.root.style.height=mobile?'auto':`${bottom+8}px`;document.getElementById('layout-toggle')?.classList.toggle('active',this.editing);}
 toggle(){if(isMobileScreen()){this.onChange('画面配置の編集は、横幅860px以上のウィンドウで行えます。スマートフォンでは下部タブで表示を切り替えられます。');return;}this.editing=!this.editing;document.getElementById('layout-tools').hidden=!this.editing;this.tools();this.apply();}
 tools(){const host=document.getElementById('layout-tools');host.innerHTML=`<span>ヘッダーで移動 · 右下でサイズ変更</span>${Object.entries(PANEL_NAMES).map(([id,name])=>`<button data-panel-toggle="${id}" class="${this.getState().layout[id].visible?'active':''}">${escapeHTML(name)}</button>`).join('')}<button data-layout-undo ${this.undoStack.length?'':'disabled'}>↶ 元に戻す</button><button data-layout-redo ${this.redoStack.length?'':'disabled'}>↷</button><button data-action="layout" class="button primary">完了</button>`;}
 setPreset(name){this.checkpoint();const s=this.getState();s.layout=presetLayout(name);s.preset=name;this.apply();this.tools();this.save();}
 togglePanel(id){if(!this.getState().layout[id])return;this.checkpoint();this.getState().layout[id].visible=!this.getState().layout[id].visible;this.getState().preset='custom';this.apply();this.tools();this.save();}
 restore(layout){this.checkpoint();this.getState().layout=normalizeLayout(layout);this.getState().preset='custom';this.apply();this.tools();this.save();}
 undo(redo=false){const from=redo?this.redoStack:this.undoStack,to=redo?this.undoStack:this.redoStack;if(!from.length)return;to.push(structuredClone(this.getState().layout));this.getState().layout=from.pop();this.getState().preset='custom';this.apply();this.tools();this.save();}
 down(e){if(!this.editing||isMobileScreen()||e.button!==0)return;const handle=e.target.closest('.panel-drag,.resize-handle');if(!handle||e.target.closest('button'))return;const panel=handle.closest('[data-panel]');if(!panel)return;e.preventDefault();this.checkpoint();const id=panel.dataset.panel;this.drag={id,pointer:e.pointerId,x:e.clientX,y:e.clientY,initial:{...this.getState().layout[id]},resize:handle.classList.contains('resize-handle'),el:handle};handle.setPointerCapture(e.pointerId);panel.classList.add('dragging');}
 move(e){const d=this.drag;if(!d||d.pointer!==e.pointerId)return;e.preventDefault();const dx=Math.round((e.clientX-d.x)/(this.root.clientWidth/24)),dy=Math.round((e.clientY-d.y)/20),p=this.getState().layout[d.id];if(d.resize){p.w=clamp(d.initial.w+dx,4,24-p.x);p.h=clamp(d.initial.h+dy,d.id==='waves'?4:8,80);}else{p.x=clamp(d.initial.x+dx,0,24-p.w);p.y=clamp(d.initial.y+dy,0,200);}this.apply();}
 up(e){if(!this.drag||this.drag.pointer!==e.pointerId)return;this.root.querySelector('.dragging')?.classList.remove('dragging');this.drag=null;this.getState().preset='custom';this.save();this.tools();}
}
